<script setup>
import { computed, reactive, ref, watch } from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue';
import { EVENT_COST_CATEGORIES, toEventCostDraft, toEventCostPayload } from '../domain/event-cost-write.mjs';
const props = defineProps({ record: { type: Object, default: () => ({}) }, category: String, editing: Boolean, saving: Boolean, error: String, suppliers: { type: Array, default: () => [] } }); const emit = defineEmits(['cancel', 'save']); const draft = reactive({ ...toEventCostDraft(props.record, props.category) }); const localError = ref(''); const title = computed(() => `${props.editing ? 'Sửa' : 'Thêm'} chi phí ${EVENT_COST_CATEGORIES.find((item) => item.value === draft.category)?.label || ''}`); const supplierOptions = computed(() => [{ value: '', label: 'Không chọn nhà cung cấp' }, ...props.suppliers.map((supplier) => ({ value: String(supplier.id), label: supplier.name }))]); watch(() => [props.record, props.category], () => Object.assign(draft, toEventCostDraft(props.record, props.category)), { deep: true }); function submit(){try{localError.value='';emit('save',toEventCostPayload(draft));}catch(error){localError.value=error.message;}}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" novalidate @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">{{ title }}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Máy chủ kiểm tra lại owner, vai trò và trường chi phí khi lưu.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Nội dung *</span><MInput v-model="draft.title" :disabled="saving" /></label><label><span class="mb-1 block text-[13px] font-medium">Số tiền (đ)</span><MInput v-model="draft.amount" type="number" min="0" :disabled="saving" /></label><label v-if="draft.category==='sponsor'"><span class="mb-1 block text-[13px] font-medium">Danh vị tài trợ</span><MInput v-model="draft.sponsor_tier" :disabled="saving" /></label><label v-if="draft.category==='organization'"><span class="mb-1 block text-[13px] font-medium">Nhà cung cấp</span><MSelect v-model="draft.supplier_id" :options="supplierOptions" :disabled="saving" /></label><label v-if="draft.category==='media'"><span class="mb-1 block text-[13px] font-medium">Đơn vị báo chí</span><MInput v-model="draft.press_org" :disabled="saving" /></label><label v-if="draft.category==='media'"><span class="mb-1 block text-[13px] font-medium">Phóng viên</span><MInput v-model="draft.journalist_name" :disabled="saving" /></label><label v-if="draft.category==='media'" class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Link nghiệm thu</span><MInput v-model="draft.article_link" type="url" placeholder="https://…" :disabled="saving" /></label><label v-if="draft.category==='sponsor'" class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Quyền lợi tài trợ</span><MTextarea v-model="draft.sponsor_benefits" :disabled="saving" /></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :disabled="saving" /></label></div><p v-if="error || localError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error || localError }}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" :disabled="saving" @click="submit">Lưu dòng chi phí</MButton></footer></form></section></template>
